-- broker-drip-2026-08-30.sql — NOT APPLIED. Waiting on Yaseen's approval.
--
-- Replaces the broker d1–d7 subjects and bodies with the draft rendered in
-- docs/outreach/BROKER-DRIP-DRAFT-2026-08-30.html.
--
-- Why: 1,409 brokers emailed, 1.99% clicked (better than carriers' 1.27%), 0 signups.
-- Six of the seven old emails asked a stranger to create an account and never said what the
-- account gives them; the zero-setup ask (cc loads@loadboot.com) appeared once, as a footnote
-- under a second button. Every new email now carries BOTH doors — the cc address as a
-- highlighted block and the free account as the single button — plus a $0 panel spelling out
-- what the free account includes and why it can be free (LoadBoot is funded by the flat 5%
-- CARRIER-side dispatch fee; brokers are never billed).
--
-- Every claim is taken from the live site: free-load-board-for-brokers.html and pricing.html.
-- If any of those pages change, re-check these bodies before re-sending.
--
-- Setting html non-null nulls `parts`, which is what makes the custom body take effect.

-- Take the backup FIRST:
--   create table if not exists app_private._outreach_templates_bak_20260830 as
--     select * from app_private.outreach_templates;


update app_private.outreach_templates
   set subject = $LBTPL$Post {STATE} loads free — carriers checked before they book$LBTPL$,
       html    = $LBTPL$<div style="display:none;max-height:0;overflow:hidden">Posting is free permanently. Every carrier is FMCSA-verified before they can bid.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:26px 12px"><table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:16px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:20px 34px" align="left"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="left"><img src="https://loadboot.com/email-logo-white-2x.png" width="146" alt="LoadBoot" style="display:block;border:0;max-width:146px;height:auto"></td><td align="right" style="font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:#8fb9e8;white-space:nowrap">Free for brokers</td></tr></table></td></tr><tr><td style="height:3px;background:#0883F7;background:linear-gradient(90deg,#0883F7 0%,#0883F7 62%,#FC5305 100%);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:30px 34px 4px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p>
<p style="margin:0 0 16px">Between posting a load and watching it pick up, somebody has to prove the carrier is real: authority active, insurance in force, and the truck at the dock being the truck on the certificate. That is the check that decides whether a load moves or becomes a claim &mdash; and it is the first one to get skipped when the clock runs out.</p>
<p style="margin:0 0 18px">LoadBoot runs it automatically at the moment a carrier books &mdash; FMCSA operating authority, insurance on record, and the truck&rsquo;s VIN matched to its certificate of insurance. A carrier that fails any of the three cannot bid on your freight.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f6fafe;border:1px solid #d9e7f7;border-radius:14px;margin:6px 0 18px"><tr><td style="padding:18px 20px 4px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#10223B;border-radius:8px;padding:5px 11px;font-size:15px;font-weight:800;color:#ffffff">$0</td><td style="padding-left:11px;font-size:15.5px;font-weight:800;color:#10223B;letter-spacing:-.01em">Everything a free broker account includes</td></tr></table></td></tr><tr><td style="padding:6px 20px 4px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">Unlimited load posting</b><br><span style="padding-left:15px;display:inline-block">no subscription, no per-post fee, no card</span></td><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">FMCSA-verified carriers only</b><br><span style="padding-left:15px;display:inline-block">authority and insurance monitored continuously</span></td></tr><tr><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">First-accept-wins offers</b><br><span style="padding-left:15px;display:inline-block">every other offer auto-closes &mdash; no double-booked trucks</span></td><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">Live GPS on every load</b><br><span style="padding-left:15px;display:inline-block">geofenced arrive and depart stamps</span></td></tr><tr><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">Rate con, BOL and POD</b><br><span style="padding-left:15px;display:inline-block">attached to the load, not to an inbox</span></td><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">One-receipt payables</b><br><span style="padding-left:15px;display:inline-block">a PAY-BY date on every dollar, both sides</span></td></tr><tr><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">Zero ghost loads</b><br><span style="padding-left:15px;display:inline-block">stale postings auto-close; cancellations carry TONU exposure</span></td><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">Claims desk and documents</b><br><span style="padding-left:15px;display:inline-block">collected against the load, not a bolt-on</span></td></tr><tr><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">Post by email</b><br><span style="padding-left:15px;display:inline-block">cc loads@loadboot.com &mdash; nothing to install</span></td><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">The phone app</b><br><span style="padding-left:15px;display:inline-block">post, watch offers and approve documents anywhere</span></td></tr></table></td></tr><tr><td style="padding:10px 20px 16px"><div style="border-top:1px solid #dbe8f6;padding-top:11px;font-size:12.5px;line-height:1.65;color:#5b6b82"><b style="color:#10223B">Why it is free:</b> LoadBoot is funded by one revenue line &mdash; a flat 5% dispatch fee on the <i>carrier</i> side. Brokers are never billed: no subscription, no tier, no per-post charge, no card on file.</div></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:2px 0 6px"><tr><td style="padding:0 0 14px"><div style="font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#5b6b82;padding-bottom:8px">Two ways in &mdash; take either</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px dashed #b9d4f0;border-radius:12px;background:#ffffff"><tr><td style="padding:15px 18px"><div style="font-size:13px;color:#5b6b82;padding-bottom:4px">1 &mdash; Nothing to set up, no account:</div><div style="font-size:20px;font-weight:800;color:#10223B;letter-spacing:-.015em;line-height:1.3">cc loads@loadboot.com</div><div style="font-size:13px;color:#5b6b82;padding-top:4px">on the load list you already send your carriers. We read the lanes, equipment, dates and rate, post each load under your company, and reply if anything is missing.</div></td></tr></table></td></tr><tr><td style="padding:0 0 4px"><div style="font-size:13px;color:#5b6b82;padding-bottom:9px">2 &mdash; Or take the whole screen &mdash; post, cover, rate con and invoice in one place:</div><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#0883F7;border-radius:10px"><a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d1&oc={OC}" style="display:inline-block;padding:14px 30px;font-size:15px;font-weight:700;color:#ffffff !important;text-decoration:none;border-radius:10px"><span style="color:#ffffff !important;text-decoration:none">Create your free broker account</span></a></td></tr></table></td></tr></table></td></tr><tr><td style="padding:18px 34px 0"><div style="border-top:1px solid #e8eef6"></div></td></tr><tr><td style="padding:16px 34px 22px;font-size:13px;line-height:1.9;color:#475569"><b style="color:#10223B">LoadBoot &middot; Broker Desk</b><br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d1&oc={OC}" style="color:#0883F7;text-decoration:none"><span style="color:#0883F7 !important;text-decoration:none">loadboot.com</span></a> &middot; +1 (469) 253-7575 &middot; available 24/7 &middot; reply to this email any time</td></tr><tr><td style="background:#f8fafc;padding:15px 34px 19px;font-size:11.5px;line-height:1.75;color:#8a94a6;border-top:1px solid #e8eef6">You are receiving this because {NAME} is listed on the public FMCSA register. If you would prefer not to hear from us, <a href="{UNSUB}" style="color:#8a94a6"><span style="color:#8a94a6 !important">unsubscribe with one click</span></a> and we will stop immediately.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</td></tr></table></td></tr></table>$LBTPL$,
       parts   = null,
       active  = true
 where audience = 'broker' and day = 1;
update app_private.outreach_templates
   set subject = $LBTPL$the five checks that catch a double-broker$LBTPL$,
       html    = $LBTPL$<div style="display:none;max-height:0;overflow:hidden">Run these on your next new carrier. Three of the five we automated.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:26px 12px"><table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:16px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:20px 34px" align="left"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="left"><img src="https://loadboot.com/email-logo-white-2x.png" width="146" alt="LoadBoot" style="display:block;border:0;max-width:146px;height:auto"></td><td align="right" style="font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:#8fb9e8;white-space:nowrap">Broker desk</td></tr></table></td></tr><tr><td style="height:3px;background:#0883F7;background:linear-gradient(90deg,#0883F7 0%,#0883F7 62%,#FC5305 100%);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:30px 34px 4px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p>
<p style="margin:0 0 16px">Double-brokering is not usually caught by intuition. It is caught by five specific checks, and the fifth is the one people skip.</p>
<p style="margin:0 0 14px"><b style="color:#10223B">1.</b> Pull the MC/DOT yourself on SAFER &mdash; do not trust the number in the email signature.<br>
<b style="color:#10223B">2.</b> Check the authority is <i>active</i>, not merely issued, and that the entity type says carrier.<br>
<b style="color:#10223B">3.</b> Call the insurance agent on the certificate at the number <i>you</i> looked up, not the one printed on it.<br>
<b style="color:#10223B">4.</b> Compare the phone and email domain against the FMCSA record. A brand-new Gmail against a five-year-old docket is worth one question.<br>
<b style="color:#10223B">5.</b> <b>Match the VIN of the truck that shows up to the VIN scheduled on the certificate of insurance.</b> This is the one that separates a real carrier from somebody who re-posted your load &mdash; a double-broker cannot produce it.</p>
<p style="margin:0 0 18px">Checks 1, 2 and 5 are the ones we automated. On LoadBoot they run at the moment of booking, on every carrier, every time &mdash; nobody has to remember at 5 PM on a Friday. Even if you never use us, run check 5 on your next new carrier: it costs one photo and it catches what the other four miss.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f6fafe;border:1px solid #d9e7f7;border-radius:12px;margin:4px 0 16px"><tr><td style="padding:14px 18px;font-size:13.5px;line-height:1.7;color:#5b6b82"><b style="color:#10223B;font-size:14px">A broker account is free, permanently.</b><br>Unlimited posting, FMCSA-verified carriers, live GPS, rate con / BOL / POD on the load, and one-receipt payables &mdash; no subscription, no per-post fee, no card. LoadBoot is funded by a flat 5% dispatch fee on the <i>carrier</i> side; brokers are never billed.</td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:2px 0 6px"><tr><td style="padding:0 0 14px"><div style="font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#5b6b82;padding-bottom:8px">Two ways in &mdash; take either</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px dashed #b9d4f0;border-radius:12px;background:#ffffff"><tr><td style="padding:15px 18px"><div style="font-size:13px;color:#5b6b82;padding-bottom:4px">1 &mdash; Nothing to set up, no account:</div><div style="font-size:20px;font-weight:800;color:#10223B;letter-spacing:-.015em;line-height:1.3">cc loads@loadboot.com</div><div style="font-size:13px;color:#5b6b82;padding-top:4px">on the load list you already send your carriers. We read the lanes, equipment, dates and rate, post each load under your company, and reply if anything is missing.</div></td></tr></table></td></tr><tr><td style="padding:0 0 4px"><div style="font-size:13px;color:#5b6b82;padding-bottom:9px">2 &mdash; Or take the whole screen &mdash; post, cover, rate con and invoice in one place:</div><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#0883F7;border-radius:10px"><a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d2&oc={OC}" style="display:inline-block;padding:14px 30px;font-size:15px;font-weight:700;color:#ffffff !important;text-decoration:none;border-radius:10px"><span style="color:#ffffff !important;text-decoration:none">Create your free broker account</span></a></td></tr></table></td></tr></table></td></tr><tr><td style="padding:18px 34px 0"><div style="border-top:1px solid #e8eef6"></div></td></tr><tr><td style="padding:16px 34px 22px;font-size:13px;line-height:1.9;color:#475569"><b style="color:#10223B">LoadBoot &middot; Broker Desk</b><br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d2&oc={OC}" style="color:#0883F7;text-decoration:none"><span style="color:#0883F7 !important;text-decoration:none">loadboot.com</span></a> &middot; +1 (469) 253-7575 &middot; available 24/7 &middot; reply to this email any time</td></tr><tr><td style="background:#f8fafc;padding:15px 34px 19px;font-size:11.5px;line-height:1.75;color:#8a94a6;border-top:1px solid #e8eef6">You are receiving this because {NAME} is listed on the public FMCSA register. If you would prefer not to hear from us, <a href="{UNSUB}" style="color:#8a94a6"><span style="color:#8a94a6 !important">unsubscribe with one click</span></a> and we will stop immediately.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</td></tr></table></td></tr></table>$LBTPL$,
       parts   = null,
       active  = true
 where audience = 'broker' and day = 2;
update app_private.outreach_templates
   set subject = $LBTPL$the check call nobody has time to make$LBTPL$,
       html    = $LBTPL$<div style="display:none;max-height:0;overflow:hidden">Location on every load without ringing the driver twice a day.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:26px 12px"><table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:16px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:20px 34px" align="left"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="left"><img src="https://loadboot.com/email-logo-white-2x.png" width="146" alt="LoadBoot" style="display:block;border:0;max-width:146px;height:auto"></td><td align="right" style="font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:#8fb9e8;white-space:nowrap">Free for brokers</td></tr></table></td></tr><tr><td style="height:3px;background:#0883F7;background:linear-gradient(90deg,#0883F7 0%,#0883F7 62%,#FC5305 100%);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:30px 34px 4px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p>
<p style="margin:0 0 16px">A check call is a person interrupting a driver to ask a question the driver&rsquo;s phone already knows the answer to. Two a day across thirty loads a week is somebody&rsquo;s entire job &mdash; and your customer still rings you to ask where the truck is.</p>
<p style="margin:0 0 18px">On LoadBoot the carrier&rsquo;s app posts location against the load itself, with geofenced arrive and depart stamps. You see it, and your customer sees it if you want them to. The part that matters for {STATE} freight: when a load is running late you know while it can still be fixed, instead of at the appointment.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f6fafe;border:1px solid #d9e7f7;border-radius:12px;margin:4px 0 16px"><tr><td style="padding:14px 18px;font-size:13.5px;line-height:1.7;color:#5b6b82"><b style="color:#10223B;font-size:14px">A broker account is free, permanently.</b><br>Unlimited posting, FMCSA-verified carriers, live GPS, rate con / BOL / POD on the load, and one-receipt payables &mdash; no subscription, no per-post fee, no card. LoadBoot is funded by a flat 5% dispatch fee on the <i>carrier</i> side; brokers are never billed.</td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:2px 0 6px"><tr><td style="padding:0 0 14px"><div style="font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#5b6b82;padding-bottom:8px">Two ways in &mdash; take either</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px dashed #b9d4f0;border-radius:12px;background:#ffffff"><tr><td style="padding:15px 18px"><div style="font-size:13px;color:#5b6b82;padding-bottom:4px">1 &mdash; Nothing to set up, no account:</div><div style="font-size:20px;font-weight:800;color:#10223B;letter-spacing:-.015em;line-height:1.3">cc loads@loadboot.com</div><div style="font-size:13px;color:#5b6b82;padding-top:4px">on the load list you already send your carriers. We read the lanes, equipment, dates and rate, post each load under your company, and reply if anything is missing.</div></td></tr></table></td></tr><tr><td style="padding:0 0 4px"><div style="font-size:13px;color:#5b6b82;padding-bottom:9px">2 &mdash; Or take the whole screen &mdash; post, cover, rate con and invoice in one place:</div><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#0883F7;border-radius:10px"><a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d3&oc={OC}" style="display:inline-block;padding:14px 30px;font-size:15px;font-weight:700;color:#ffffff !important;text-decoration:none;border-radius:10px"><span style="color:#ffffff !important;text-decoration:none">Create your free broker account</span></a></td></tr></table></td></tr></table></td></tr><tr><td style="padding:18px 34px 0"><div style="border-top:1px solid #e8eef6"></div></td></tr><tr><td style="padding:16px 34px 22px;font-size:13px;line-height:1.9;color:#475569"><b style="color:#10223B">LoadBoot &middot; Broker Desk</b><br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d3&oc={OC}" style="color:#0883F7;text-decoration:none"><span style="color:#0883F7 !important;text-decoration:none">loadboot.com</span></a> &middot; +1 (469) 253-7575 &middot; available 24/7 &middot; reply to this email any time</td></tr><tr><td style="background:#f8fafc;padding:15px 34px 19px;font-size:11.5px;line-height:1.75;color:#8a94a6;border-top:1px solid #e8eef6">You are receiving this because {NAME} is listed on the public FMCSA register. If you would prefer not to hear from us, <a href="{UNSUB}" style="color:#8a94a6"><span style="color:#8a94a6 !important">unsubscribe with one click</span></a> and we will stop immediately.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</td></tr></table></td></tr></table>$LBTPL$,
