update app_private.outreach_templates
   set subject = $LBTPL$detention that actually gets paid$LBTPL$,
       html    = $LBTPL$<div style="display:none;max-height:0;overflow:hidden">Timestamps beat a phone call and a memory. Our policy is public — copy it.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:26px 12px"><table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:16px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:20px 34px" align="left"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="left"><img src="https://loadboot.com/email-logo-white-2x.png" width="146" alt="LoadBoot" style="display:block;border:0;max-width:146px;height:auto"></td><td align="right" style="font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:#8fb9e8;white-space:nowrap">Broker desk</td></tr></table></td></tr><tr><td style="height:3px;background:#0883F7;background:linear-gradient(90deg,#0883F7 0%,#0883F7 62%,#FC5305 100%);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:30px 34px 4px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p>
<p style="margin:0 0 16px">Detention arguments are almost never about whether the truck waited. They are about whether anyone can prove when it arrived.</p>
<p style="margin:0 0 16px">The version that gets paid looks like this: arrival and departure timestamped by the driver&rsquo;s own device, a written free-time figure both sides agreed to before dispatch, and an accessorial raised the same day rather than three weeks later on an invoice nobody expected. The version that does not get paid is a phone call and a memory.</p>
<p style="margin:0 0 18px">We published our detention policy so a carrier can read it before booking and a shipper can read it before arguing: <a href="https://loadboot.com/detention-pay-policy.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d4&oc={OC}" style="color:#0883F7">loadboot.com/detention-pay-policy</a>. Copy it if it is useful &mdash; it is not proprietary.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f6fafe;border:1px solid #d9e7f7;border-radius:12px;margin:4px 0 16px"><tr><td style="padding:14px 18px;font-size:13.5px;line-height:1.7;color:#5b6b82"><b style="color:#10223B;font-size:14px">A broker account is free, permanently.</b><br>Unlimited posting, FMCSA-verified carriers, live GPS, rate con / BOL / POD on the load, and one-receipt payables &mdash; no subscription, no per-post fee, no card. LoadBoot is funded by a flat 5% dispatch fee on the <i>carrier</i> side; brokers are never billed.</td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:2px 0 6px"><tr><td style="padding:0 0 14px"><div style="font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#5b6b82;padding-bottom:8px">Two ways in &mdash; take either</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px dashed #b9d4f0;border-radius:12px;background:#ffffff"><tr><td style="padding:15px 18px"><div style="font-size:13px;color:#5b6b82;padding-bottom:4px">1 &mdash; Nothing to set up, no account:</div><div style="font-size:20px;font-weight:800;color:#10223B;letter-spacing:-.015em;line-height:1.3">cc loads@loadboot.com</div><div style="font-size:13px;color:#5b6b82;padding-top:4px">on the load list you already send your carriers. We read the lanes, equipment, dates and rate, post each load under your company, and reply if anything is missing.</div></td></tr></table></td></tr><tr><td style="padding:0 0 4px"><div style="font-size:13px;color:#5b6b82;padding-bottom:9px">2 &mdash; Or take the whole screen &mdash; post, cover, rate con and invoice in one place:</div><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#0883F7;border-radius:10px"><a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d4&oc={OC}" style="display:inline-block;padding:14px 30px;font-size:15px;font-weight:700;color:#ffffff !important;text-decoration:none;border-radius:10px"><span style="color:#ffffff !important;text-decoration:none">Create your free broker account</span></a></td></tr></table></td></tr></table></td></tr><tr><td style="padding:18px 34px 0"><div style="border-top:1px solid #e8eef6"></div></td></tr><tr><td style="padding:16px 34px 22px;font-size:13px;line-height:1.9;color:#475569"><b style="color:#10223B">LoadBoot &middot; Broker Desk</b><br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d4&oc={OC}" style="color:#0883F7;text-decoration:none"><span style="color:#0883F7 !important;text-decoration:none">loadboot.com</span></a> &middot; +1 (469) 253-7575 &middot; available 24/7 &middot; reply to this email any time</td></tr><tr><td style="background:#f8fafc;padding:15px 34px 19px;font-size:11.5px;line-height:1.75;color:#8a94a6;border-top:1px solid #e8eef6">You are receiving this because {NAME} is listed on the public FMCSA register. If you would prefer not to hear from us, <a href="{UNSUB}" style="color:#8a94a6"><span style="color:#8a94a6 !important">unsubscribe with one click</span></a> and we will stop immediately.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</td></tr></table></td></tr></table>$LBTPL$,
       parts   = null,
       active  = true
 where audience = 'broker' and day = 4;
update app_private.outreach_templates
   set subject = $LBTPL$5:40 PM Friday, one truck, freight on the dock$LBTPL$,
       html    = $LBTPL$<div style="display:none;max-height:0;overflow:hidden">The most pressured cover of the week, vetted like the calmest one.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:26px 12px"><table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#ffffff;border-radius:16px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:20px 34px" align="left"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="left"><img src="https://loadboot.com/email-logo-white-2x.png" width="146" alt="LoadBoot" style="display:block;border:0;max-width:146px;height:auto"></td><td align="right" style="font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:#8fb9e8;white-space:nowrap">Free for brokers</td></tr></table></td></tr><tr><td style="height:3px;background:#0883F7;background:linear-gradient(90deg,#0883F7 0%,#0883F7 62%,#FC5305 100%);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:30px 34px 4px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p>
<p style="margin:0 0 16px">Vetting a carrier is easy on a Monday morning. It fails at 5:40 PM on a Friday, with freight on the dock and one truck available &mdash; because that is the moment somebody decides the paperwork can wait until Monday.</p>
<p style="margin:0 0 18px">Verification on LoadBoot runs at booking, not at onboarding, so your most pressured cover of the week is held to exactly the same standard as your calmest one: authority, insurance, safety record and VIN-to-COI, every time, at any hour. Nothing about that is a paid tier &mdash; it is what the free account does.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f6fafe;border:1px solid #d9e7f7;border-radius:14px;margin:6px 0 18px"><tr><td style="padding:18px 20px 4px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#10223B;border-radius:8px;padding:5px 11px;font-size:15px;font-weight:800;color:#ffffff">$0</td><td style="padding-left:11px;font-size:15.5px;font-weight:800;color:#10223B;letter-spacing:-.01em">Everything a free broker account includes</td></tr></table></td></tr><tr><td style="padding:6px 20px 4px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">Unlimited load posting</b><br><span style="padding-left:15px;display:inline-block">no subscription, no per-post fee, no card</span></td><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">FMCSA-verified carriers only</b><br><span style="padding-left:15px;display:inline-block">authority and insurance monitored continuously</span></td></tr><tr><td width="50%" valign="top" style="padding:7px 10px 7px 0;font-size:13.5px;line-height:1.55;color:#5b6b82"><span style="color:#0883F7;font-weight:700">&#10003;</span> <b style="color:#10223B">First-accept-wins offers</b><br><span style="padding-left:15px;display:inline-block">every other offer auto-closes &mdash; no